// The chart, headline stats, and every number inside DATASETS/FINDINGS below
// are filled in from frontend/evaluation-data.json at load time, not
// hand-typed — that file is generated by eval/generate_summary_tables.py
// directly from eval/scale_results/*.json, so this page can't drift from
// the underlying data the way it once did (see "Recall@5 counting bug" in
// VALIDATION.md for what happened the one time numbers were hand-typed and
// never re-derived). Re-run that script after any change to the eval data;
// this file only supplies the surrounding prose and two numbers that aren't
// in any scale_results file — see the concurrency comment below.

function esc(text) {
  const d = document.createElement('div');
  d.appendChild(document.createTextNode(String(text || '')));
  return d.innerHTML;
}

document.getElementById('brandMark').innerHTML = svgIcon('layers', 16);
document.getElementById('backLink').innerHTML = svgIcon('home', 15) + '<span>Back to app</span>';
document.getElementById('kickerBadge').innerHTML = svgIcon('bar-chart', 13) + '<span>Retrieval evaluation</span>';
document.getElementById('chartSectionLabel').innerHTML = svgIcon('activity', 13) + '<span>Retrieval quality vs. corpus size</span>';
document.getElementById('datasetsLabel').innerHTML = svgIcon('database', 13) + '<span>Evaluation datasets</span>';
document.getElementById('findingsLabel').innerHTML = svgIcon('search', 13) + '<span>What was found, in order</span>';
document.getElementById('limitationsTitle').innerHTML = svgIcon('alert-triangle', 17) + '<span>Known limitations</span>';
document.getElementById('linksLabel').innerHTML = svgIcon('file-text', 13) + '<span>Full detail</span>';
['linkIcon1','linkIcon2','linkIcon3'].forEach(function(id){ document.getElementById(id).innerHTML = svgIcon('file-text', 15); });

function pct1(frac) { return (frac * 100).toFixed(1); }

function buildChart(ladder) {
  var labels = ladder.map(function(p) { return p.corpus_size.toLocaleString(); });
  var recall = ladder.map(function(p) { return p.golden_recall_frac; });
  var mrr = ladder.map(function(p) { return p.golden_mrr; });
  var COL_RECALL = '#199e70', COL_MRR = '#3987e5';

  var W = 640, H = 280, padL = 46, padR = 56, padT = 20, padB = 34;
  var plotW = W - padL - padR, plotH = H - padT - padB;
  var n = labels.length;
  var xAt = function(i) { return padL + (plotW / (n - 1)) * i; };
  var yAt = function(v) { return padT + plotH - v * plotH; };

  function pathFor(vals) {
    return vals.map(function(v, i) { return (i === 0 ? 'M' : 'L') + xAt(i).toFixed(1) + ',' + yAt(v).toFixed(1); }).join(' ');
  }
  function dotsFor(vals, color, fmt) {
    return vals.map(function(v, i) {
      var cx = xAt(i).toFixed(1), cy = yAt(v).toFixed(1);
      return '<circle cx="' + cx + '" cy="' + cy + '" r="4.5" fill="' + color + '" stroke="var(--surface)" stroke-width="2">' +
        '<title>' + labels[i] + ' documents — ' + fmt(v) + '</title></circle>';
    }).join('');
  }

  var gridLevels = [0, 0.25, 0.5, 0.75, 1.0];
  var grid = gridLevels.map(function(v) {
    var y = yAt(v).toFixed(1);
    return '<line x1="' + padL + '" y1="' + y + '" x2="' + (W - padR) + '" y2="' + y + '" stroke="var(--border)" stroke-width="1"/>' +
      '<text x="' + (padL - 10) + '" y="' + (y * 1 + 3.5) + '" text-anchor="end" class="chart-axis-label">' + v.toFixed(2) + '</text>';
  }).join('');

  var xLabels = labels.map(function(l, i) {
    return '<text x="' + xAt(i).toFixed(1) + '" y="' + (H - 10) + '" text-anchor="middle" class="chart-axis-label">' + l + '</text>';
  }).join('');

  var endRecall = xAt(n - 1) + 8, endRecallY = yAt(recall[n - 1]);
  var endMrr = xAt(n - 1) + 8, endMrrY = yAt(mrr[n - 1]);

  var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="xMidYMid meet">' +
    grid + xLabels +
    '<path d="' + pathFor(recall) + '" fill="none" stroke="' + COL_RECALL + '" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>' +
    '<path d="' + pathFor(mrr) + '" fill="none" stroke="' + COL_MRR + '" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>' +
    dotsFor(recall, COL_RECALL, function(v){ return pct1(v) + '% Recall@5'; }) +
    dotsFor(mrr, COL_MRR, function(v){ return v.toFixed(3) + ' MRR'; }) +
    '<text x="' + (endRecall) + '" y="' + (endRecallY - 6) + '" class="chart-axis-label" fill="' + COL_RECALL + '" font-weight="600">' + pct1(recall[n-1]) + '%</text>' +
    '<text x="' + (endMrr) + '" y="' + (endMrrY + 14) + '" class="chart-axis-label" fill="' + COL_MRR + '" font-weight="600">' + mrr[n-1].toFixed(3) + '</text>' +
    '</svg>';

  document.getElementById('chartWrap').innerHTML = svg;
}

function render(data) {
  var first = data.ladder[0], last = data.ladder[data.ladder.length - 1];
  buildChart(data.ladder);

  document.getElementById('statRecallValue').textContent =
    pct1(last.golden_recall_frac) + ' / ' + pct1(last.heldout_recall_frac) + '%';
  document.getElementById('statRecallLabel').textContent =
    'golden / held-out strict Recall@5 at ' + last.corpus_size.toLocaleString() + ' docs — down from ' +
    pct1(first.golden_recall_frac) + ' / ' + pct1(first.heldout_recall_frac) + '% at ' + first.corpus_size.toLocaleString();

  var idFreeBefore = data.id_free_before.natural_lookup_by_number;
  var idFreeAfter = data.id_free_after.natural_lookup_by_number;
  var idFreeOverall = data.id_free_after_overall;
  var cite = data.citation_heldout;
  var split = cite.issuer_bracket_split;

  // ── Dataset cards ────────────────────────────────────────────────────────
  var DATASETS = [
    {
      name: 'Golden + held-out', badge: 'good', badgeText: 'core ladder',
      desc: 'The calibration set (150 questions, used to tune RELEVANCE_THRESHOLD) plus a held-out set never touched during that tuning. Every positive question names the target document’s exact CELEX ID — tracks the structured-lookup path and rank position (MRR) across all 5 scale checkpoints.'
    },
    {
      name: 'ID-free spot-check', badge: 'good',
      badgeText: pct1(idFreeOverall.strict / idFreeOverall.n) + '% strict R@5',
      desc: idFreeOverall.n + ' questions with no ID or citation number in the text at all — natural subject lookup, date facts, cross-references, and disambiguating one document out of a 509-member near-duplicate cluster by date alone. Tests dense+sparse search with no structured-index shortcut.'
    },
    {
      name: 'Citation-number generalization', badge: 'warn',
      badgeText: svgIcon('alert-triangle', 11) + ' Known limitation — ' + pct1(cite.overall.strict / cite.overall.n) + '% R@5',
      desc: cite.overall.n + ' brand-new documents (zero overlap with any other set), 5 natural citation phrasings. Built specifically because re-testing a fix on the same questions that found it doesn’t prove it generalizes — it didn’t fully, and this is why: a real, still-open gap, not a bad-luck number. See "Known limitations" below.'
    },
    {
      name: 'Consistency + concurrency', badge: 'good', badgeText: '300/300 answers',
      desc: 'Same questions repeated 20x each at 57,000 docs — 300/300 final answers correct, though retrieval picked a different top document on 1 of 15 questions (a leading indicator, not a wrong answer). Concurrency tested against the full 57k index for the first time in this pass.'
    },
  ];
  document.getElementById('datasetGrid').innerHTML = DATASETS.map(function(d) {
    return '<div class="dataset-card"><div class="dataset-card-head"><span class="dataset-name">' + d.name + '</span>' +
      '<span class="dataset-badge ' + d.badge + '">' + d.badgeText + '</span></div>' +
      '<div class="dataset-desc">' + d.desc + '</div></div>';
  }).join('');

  // ── Findings ─────────────────────────────────────────────────────────────
  var FINDINGS = [
    {
      category: 'Retrieval',
      problem: 'Natural short-citation lookup had no structured index.',
      evidence: pct1(idFreeBefore.strict / idFreeBefore.n) + '% Recall@5 on ID-free citation lookup — confused two documents sharing the same number a year apart.',
      fix: 'Added a structured (number, year) index, mirroring the existing CELEX-ID lookup.',
      result: pct1(idFreeAfter.strict / idFreeAfter.n) + '% strict Recall@5 on that question type.',
      detail: 'The full document ID (CELEX ID) had a dedicated lookup, but the natural way a person actually cites EU legislation — "Regulation (EC) No 480/86" — fell back to plain semantic search, which confused it with an unrelated document sharing the same number a year apart. Found via a 120-question ID-free test built specifically to remove the ID shortcut.'
    },
    {
      category: 'Ground truth',
      problem: 'Ground truth only accepted the first citation a document supported.',
      evidence: 'EU legal preambles routinely cite several earlier regulations legitimately — correct-but-different model answers were being marked wrong.',
      fix: 'Ground truth now accepts any citation a document body actually supports, not just the first regex match.',
      result: 'A related ambiguous hard-negative test case (shared ground-truth date across a cluster) was also caught and fixed.',
      detail: 'Questions asking what earlier regulation a document cites only had one "correct" answer in the eval data, even though EU legal preambles routinely cite several earlier regulations legitimately. Also found: a hard disambiguation test case had an ambiguous ground-truth date shared by two other documents in its cluster — the builder now requires a chosen date to be unique across the entire cluster, not just among already-picked members.'
    },
    {
      category: 'Evaluation itself',
      problem: 'The headline Recall@5 metric was miscounting its own results.',
      evidence: 'A flat "100% throughout" headline across a 140x corpus-size range was the tell.',
      fix: 'Recomputed with strict rank ≤ 5, then independently re-verified with a fresh live run.',
      result: 'Corrected to a real ' + Math.round(first.golden_recall_frac * 100) + '% → ' + Math.round(last.golden_recall_frac * 100) + '% decline as the corpus grows.',
      detail: 'Recall@5 was computed by checking whether the target document appeared anywhere in the API’s returned sources — which can be 6 wide, not 5, when a structured-ID override force-adds a document. Recomputed from saved per-case data (nothing needed re-running to catch the mistake), then every affected dataset was re-run live against the real 57,000-document corpus to confirm the fix, not just assumed.'
    },
  ];
  document.getElementById('findingsList').innerHTML = FINDINGS.map(function(f, i) {
    return '<div class="finding"><div class="finding-num">' + (i + 1) + '</div><div class="finding-body">' +
      '<div class="finding-cat">' + esc(f.category) + '</div>' +
      '<dl class="finding-grid">' +
        '<dt>Problem</dt><dd>' + f.problem + '</dd>' +
        '<dt>Evidence</dt><dd>' + f.evidence + '</dd>' +
        '<dt>Fix</dt><dd>' + f.fix + '</dd>' +
        '<dt>Result</dt><dd class="finding-result">' + f.result + '</dd>' +
      '</dl>' +
      '<details class="finding-details"><summary>Full methodology</summary><p>' + f.detail + '</p></details>' +
      '</div></div>';
  }).join('');

  // ── Limitations ──────────────────────────────────────────────────────────
  var mismatchPct = Math.round(100 * split.mismatched_strict / split.mismatched_n);
  var LIMITATIONS = [
    '<strong>Citation rank-sensitivity is still open.</strong> When a query names the wrong issuing institution ("Council Regulation" for a document that’s actually a Commission regulation), the document is still always found (index guarantees recall), but strict Recall@5 drops from 100% to ' + mismatchPct + '% (' + split.mismatched_strict + '/' + split.mismatched_n + ') — usually landing at exactly rank 6, one place outside the window. Root-caused to the identity-match promotion path appending late matches without re-sorting by score. Two fixes identified, neither implemented — left open deliberately rather than papered over.',
    // 2.68x / 1.18x: scripts/concurrency_test.py doesn't write a results
    // file (see eval/scale_results/run_config.json's concurrency_test
    // note) — these two numbers are the one pair on this page NOT sourced
    // from evaluation-data.json, transcribed directly from that script's
    // stdout on 2026-07-15. Re-run it and update these by hand if retested.
    '<strong>Concurrency degrades substantially at scale.</strong> Concurrent-request speedup drops from 2.68x at 400 documents to 1.18x at 57,000 — under the system’s own "little to no gain" threshold. Reranking pools several times more candidates per query at this scale, and that step runs on a single dedicated GPU worker by design.',
    '<strong>Findings are specific to this corpus’s shape.</strong> EU legislation was chosen for its unusually high near-duplicate density (the same regulation type reissued monthly for decades) — a harder, not just bigger, test. A corpus of 57,000 genuinely distinct documents might show a flatter decline curve.',
    '57,000 was the ceiling of the available dataset, not a proven system limit — whether the decline continues, flattens, or eventually costs more than rank position beyond that point is genuinely unknown.',
  ];
  document.getElementById('limitationsList').innerHTML = LIMITATIONS.map(function(l) { return '<li>' + l + '</li>'; }).join('');
}

fetch('evaluation-data.json')
  .then(function(r) { if (!r.ok) throw new Error('fetch failed: ' + r.status); return r.json(); })
  .then(render)
  .catch(function(e) {
    console.error('Failed to load evaluation-data.json — re-run eval/generate_summary_tables.py:', e);
    document.getElementById('chartWrap').innerHTML =
      '<div style="padding:24px;color:var(--text-muted);font-size:13px">Evaluation data unavailable — run <code>python eval/generate_summary_tables.py</code> to generate frontend/evaluation-data.json.</div>';
  });
